const a={baseUrl:"https://api.debtfrie.com/api"},c=async(o,t={})=>{try{const r=await fetch(`${a.baseUrl}/odoo/create-lead`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({formData:o,utmParams:t})});if(!r.ok){const e=await r.json().catch(()=>({}));throw new Error(e.error||`HTTP error! status: ${r.status}`)}return await r.json()}catch(r){throw console.error("Error calling Backend Odoo API:",r),r}};export{c};
